// Openings (plan.md OPENINGS; elements 3, 9, 15, 17, 35): the glass and doors the shell leaves as air.
// Front and back windows use vocab's sashWindow (panes run along x in a z-wall). The bay's diagonal side lights sit
// in x-planes, so they get sashSide (panes along z). Front sills and hoods are the facade part's (P4); this part
// adds the back sills and hoods only (z33). Writes go into air only; runParts refuses anything the shell owns.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { FRONT_Z, BACK_Z, GLASS_PANE, sashWindow, sill, hood, garageDoor, doorPair } from "../vocab.mjs";

/** A window in an x-plane wall (the bay's diagonal sides at x1 and x6): panes run along z; a 3-high one gets a rail. */
function sashSide(g, x, y0, y1, z) {
  const pane = { north: "true", south: "true", east: "false", west: "false" };
  for (let y = y0; y <= y1; y++)
    g.set(x, y, z, ...(y1 - y0 === 2 && y === y0 + 1 ? B.slab("smooth_quartz", "bottom") : [GLASS_PANE, pane]));
}

/** A one-wide door (the garden store): lower and upper halves at x, hinge left, facing `facing`. */
function doorSingle(g, x, y, z, facing) {
  for (const [dy, half] of [[0, "lower"], [1, "upper"]]) g.set(x, y + dy, z, ...B.door("crimson", facing, half, "left"));
}

export function build(g) {
  // Street face (z7): garage door, cellar light, parlour side light, the 2nd and top floor pairs.
  garageDoor(g);
  sashWindow(g, { x0: 8, x1: 8, y0: 2, y1: 2, z: FRONT_Z });                  // cellar light
  sashWindow(g, { x0: 8, x1: 8, y0: 5, y1: 7, z: FRONT_Z });                  // parlour side light
  for (const x of [9, 12]) {
    sashWindow(g, { x0: x, x1: x, y0: 9, y1: 11, z: FRONT_Z });               // 2nd floor
    sashWindow(g, { x0: x, x1: x, y0: 13, y1: 14, z: FRONT_Z });              // top floor
  }

  // Front door pair at z10 (hinges outward) with its transom.
  doorPair(g, 11, 5, 10, "south");
  sashWindow(g, { x0: 11, x1: 12, y0: 7, y1: 7, z: 10 });

  // Angled bay: three lights per storey, two on the z5 front and one each on the x1 and x6 diagonals.
  for (const [y0, y1] of [[5, 7], [9, 11], [13, 14]]) {
    sashWindow(g, { x0: 3, x1: 4, y0, y1, z: 5 });
    sashSide(g, 1, y0, y1, 6);
    sashSide(g, 6, y0, y1, 6);
  }

  // Garden face (z32): garden-store door and window, kitchen windows, French doors, upper windows.
  doorSingle(g, 3, 1, BACK_Z, "north");
  sashWindow(g, { x0: 7, x1: 8, y0: 2, y1: 3, z: BACK_Z });
  for (const [x0, x1] of [[3, 4], [11, 12]]) sashWindow(g, { x0, x1, y0: 5, y1: 7, z: BACK_Z });
  doorPair(g, 7, 5, BACK_Z, "north");
  sashWindow(g, { x0: 7, x1: 8, y0: 7, y1: 7, z: BACK_Z });                   // French door transom
  for (const [x0, x1] of [[3, 4], [7, 8]]) sashWindow(g, { x0, x1, y0: 9, y1: 11, z: BACK_Z });
  sashWindow(g, { x0: 11, x1: 11, y0: 10, y1: 11, z: BACK_Z });              // bathroom
  sashWindow(g, { x0: 7, x1: 8, y0: 13, y1: 15, z: BACK_Z });

  // Back sills and hoods (z33). Sills sit one row under each window; hoods one row over it.
  const TRIM = BACK_Z + 1;
  for (const [x0, x1, y0, y1] of [[3, 4, 5, 7], [11, 12, 5, 7], [3, 4, 9, 11], [7, 8, 9, 11], [11, 11, 10, 11], [7, 8, 13, 15]]) {
    sill(g, x0, x1, y0, TRIM);
    hood(g, x0, x1, y1 + 1, TRIM);
  }
  sill(g, 7, 8, 2, TRIM);                                                    // garden store: no hood (its row is the deck floor)
  hood(g, 7, 8, 8, TRIM);                                                    // over the French doors
}

// Openings (plan.md OPENINGS; elements 3, 9, 15, 17, 35): the back sills and hoods (z33).
// The glass and doors are NOT placed here: the shell carves every opening to air and runParts locks those cells
// (air included), so each window and door write was refused. Restoring them needs the shell to leave the opening
// cells unowned; the removed calls are in the git-less copy at /tmp/probe5/openings.orig.mjs.
import { BACK_Z, sill, hood } from "../vocab.mjs";

export function build(g) {
  // Back sills and hoods (z33). Sills sit one row under each window; hoods one row over it.
  const TRIM = BACK_Z + 1;
  for (const [x0, x1, y0, y1] of [[3, 4, 5, 7], [11, 12, 5, 7], [3, 4, 9, 11], [7, 8, 9, 11], [11, 11, 10, 11], [7, 8, 13, 15]]) {
    sill(g, x0, x1, y0, TRIM);
    hood(g, x0, x1, y1 + 1, TRIM);
  }
  sill(g, 7, 8, 2, TRIM);                                                    // garden store: no hood (its row is the deck floor)
  hood(g, 7, 8, 8, TRIM);                                                    // over the French doors
}
